<?php function e(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');} function csrf_token():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];} function verify_csrf(?string $t):void{if(!$t||empty($_SESSION['csrf'])||!hash_equals($_SESSION['csrf'],$t)){http_response_code(419);exit('Invalid security token.');}} function require_login():void{if(empty($_SESSION['user_id'])){header('Location:/login');exit;}} function require_admin():void{require_login();if(($_SESSION['role']??'')!=='admin'){http_response_code(403);exit('Forbidden');}} function login_user(array $u):void{session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['role']=$u['role'];$_SESSION['username']=$u['username'];$_SESSION['csrf']=bin2hex(random_bytes(32));}